    /// How long the test waits on the node before failing. Each wait ends
    /// the moment what it waits for happens, so this only bounds a hang:
    /// five seconds failed a dial and a start on a Mac building its system
    /// beside the tests, so it's the link tests' thirty.
    const PATIENCE: Duration = Duration::from_secs(30);

    #[test]
    fn logs_that_cant_be_read_continue_nothing_and_say_so_once() {
        let dir = tempfile::tempdir().expect("a temporary folder");
        let logs = dir.path().join("sessions");
        fs::write(&logs, "not a folder\n").expect("written");
        let unreadable = through::Unreadable::default();
        assert!(
            continuing(&logs, &unreadable).is_none(),
            "read as empty, a claim that should pass on would lapse"
        );
        let why = format!(
            "claims that lapse are kept, as the logs under {} can't be read: {}",
            logs.display(),
            fs::read_dir(&logs).expect_err("not a folder")
        );
        assert!(!unreadable.first(&why), "it was said: {why}");
    }

    #[test]
    fn logs_that_read_say_what_each_continues() {
        let dir = tempfile::tempdir().expect("a temporary folder");
        let session = "01a1667f-f5bc-7ba6-9290-033e899fff34";
        let folder = dir.path().join("--home-joel--");
        fs::create_dir_all(&folder).expect("made");
        fs::write(
            folder.join(format!("2026-11-24T10-00-00-000Z_{session}.jsonl")),
            format!("{{\"id\":\"{session}\",\"parentSession\":\"s-steward\"}}\n"),
        )
        .expect("written");
        let continues = continuing(dir.path(), &through::Unreadable::default())
            .expect("logs that read are read");
        assert_eq!(continues(session).as_deref(), Some("s-steward"));
    }

    /// A holder in `dir` that says it holds at once, writing down in the
    /// file it answers beside it what it was given to hold. A child process
    /// puts it in place, since another test's fork holding the file open
    /// for writing would keep it from running.
    fn stand_in_holder(dir: &Path) -> (PathBuf, PathBuf) {
        let given = dir.join("given");
        let holder = dir.join("holder");
        crate::stand_in::program(
            &holder,
            &format!(
                "#!/bin/sh\nprintf '%s\\n' \"$@\" > {}\necho held\n",
                given.display()
            ),
        );
        (holder, given)
    }

    /// A node out of files, buffers or memory, or left by a client before
    /// taking it, rests and takes the next; one whose socket broke ends.
    #[test]
    fn only_a_broken_socket_ends_the_node() {
        use rustix::io::Errno;
        let error = |errno: Errno| io::Error::from_raw_os_error(errno.raw_os_error());
        for passing in [
            Errno::MFILE,
            Errno::NFILE,
            Errno::NOBUFS,
            Errno::NOMEM,
            Errno::CONNABORTED,
            Errno::INTR,
        ] {
            assert!(accept_passes(&error(passing)), "{passing:?} passes");
        }
        for ending in [Errno::BADF, Errno::INVAL, Errno::NOTSOCK] {
            assert!(!accept_passes(&error(ending)), "{ending:?} ends the node");
        }
        assert!(!accept_passes(&io::Error::other("not the system's")));
    }

    /// Holds session `0e50` on kestrel, whose store is `store`, as its
    /// holder there keeps it by `5e551011`, answering the held folder.
    fn hold_a_session(dir: &Path, store: &Memory) -> PathBuf {
        let held = dir.join("kestrel.held");
        fs::create_dir(&held).expect("the held folder is made");
        let keeps = hold::Held {
            id: "5e551011".to_owned(),
            command: vec!["pi".to_owned()],
            folder: dir.to_owned(),
            holder: std::process::id(),
            pid: 4242,
            parked: false,
            since: "2026-10-29T06:00:00Z".to_owned(),
            windows: Vec::new(),
        };
        let record = serde_json::to_vec(&keeps).expect("a record");
        fs::write(held.join("5e551011.json"), record).expect("the record is written");
        fs::write(held.join("5e551011.sock"), "").expect("its socket stands");
        let presence = json!({
            "session": "0e50",
            "addresses": ["SAK9FZ"],
            "at": "2026-10-29T06:00:00Z",
            "owner": {"pid": 4242},
        });
        store.start_here("0e50", presence, true);
        held
    }

    /// Session `id` once the node at `socket` lists it.
    async fn listed(socket: PathBuf, id: &'static str) -> Session {
        listed_as(socket, id, |_| true).await
    }

    /// Session `id` once the node at `socket` lists it as `holds` says.
    async fn listed_as(socket: PathBuf, id: &'static str, holds: fn(&Session) -> bool) -> Session {
        let listed = tokio::task::spawn_blocking(move || {
            let mut client = Client::connect(&socket).expect("the client connects");
            // Nothing tells a client when the link has carried a session,
            // so it asks again every few milliseconds until it has.
            loop {
                let Ok(Ok(Response::Sessions(all))) = client.ask(&Request::Sessions) else {
                    panic!("the node lists its sessions");
                };
                if let Some(one) = all.into_iter().find(|one| one.id == id && holds(one)) {
                    return one;
                }
                std::thread::sleep(Duration::from_millis(10));
            }
        });
        tokio::time::timeout(PATIENCE, listed)
            .await
            .expect("the node lists it in time")
            .expect("the client asks")
    }

    /// Once the node at `socket` no longer lists session `id`.
    async fn unlisted(socket: PathBuf, id: &'static str) {
        let unlisted = tokio::task::spawn_blocking(move || {
            let mut client = Client::connect(&socket).expect("the client connects");
            // Nothing tells a client when the link has let a session go,
            // so it asks again every few milliseconds until it has.
            loop {
                let Ok(Ok(Response::Sessions(all))) = client.ask(&Request::Sessions) else {
                    panic!("the node lists its sessions");
                };
                if !all.iter().any(|one| one.id == id) {
                    return;
                }
                std::thread::sleep(Duration::from_millis(10));
            }
        });
        tokio::time::timeout(PATIENCE, unlisted)
            .await
            .expect("the node lets it go in time")
            .expect("the client asks");
    }

