    #[tokio::test]
    async fn only_the_session_holding_an_orchestration_hands_it_on() {
        let dir = tempfile::tempdir().expect("a temporary folder");
        let socket = dir.path().join("skiff").join("work.sock");
        let (_stop, _node, _client) = orchestrated(&socket, &orchestrations(), &[]).await;
        steward_claims(&socket).await;
        assert_eq!(
            claims(
                &socket,
                7002,
                Some("QEST-20261108-OSPHT4"),
                &["QEST-20261115-HARBOR"]
            )
            .await,
            Err(
                "WCJQSG's session already orchestrates QEST-20261115-HARBOR by this node's \
                 record, so OSPHT4 can't: only that session hands it on, by letting go or by \
                 ending once a session continues its log, or the person"
                    .to_owned()
            ),
            "a session taking another's quest is refused"
        );
        assert_eq!(
            orders_harbour(&socket, 7002).await,
            Err(
                "OSPHT4 doesn't orchestrate QEST-20261115-HARBOR by this node's record, so it \
                 can't order its carry: only WCJQSG's session could"
                    .to_owned()
            ),
            "and orders nothing"
        );
        let read = |pid: i32| {
            asks_below(&socket, pid);
            ask(socket.clone(), Request::Orchestrating)
        };
        let none = Ok(Response::Orchestrating {
            heads: None,
            quests: Vec::new(),
        });
        assert_eq!(read(7002).await, none, "the refused claim is kept for none");
        let held = Ok(Response::Orchestrating {
            heads: Some("QEST-20261007-WCJQSG".to_owned()),
            quests: vec![
                "QEST-20261108-OSPHT4".to_owned(),
                "QEST-20261115-HARBOR".to_owned(),
            ],
        });
        assert_eq!(read(7001).await, held, "reading the claim keeps it");
        assert_eq!(read(7001).await, held, "however often it is read");
        assert_eq!(
            claims(&socket, 7001, None, &[]).await,
            Ok(Response::Orchestrated),
            "the steward releases what it held"
        );
        assert_eq!(read(7001).await, none, "and holds none once it lets go");
        assert_eq!(
            claims(
                &socket,
                7002,
                Some("QEST-20261108-OSPHT4"),
                &["QEST-20261115-HARBOR"]
            )
            .await,
            Ok(Response::Orchestrated),
            "and another session may take it up"
        );
        let kept = chain::Orchestrations::read(&socket.with_file_name("orchestrations.json"))
            .expect("the record reads");
        assert_eq!(
            kept.sessions.keys().collect::<Vec<_>>(),
            ["s-weigh"],
            "the node keeps what it was told"
        );
    }

    #[tokio::test]
    async fn a_session_whose_log_continues_a_stopped_orchestrator_takes_on_its_quests() {
        let dir = tempfile::tempdir().expect("a temporary folder");
        let socket = dir.path().join("skiff").join("work.sock");
        let store = Memory::default();
        let (_stop, _node, _client) =
            orchestrated_in(&store, &socket, &orchestrations(), &[]).await;
        steward_claims(&socket).await;
        let quests = ["QEST-20261108-OSPHT4", "QEST-20261115-HARBOR"];
        assert!(
            claims(&socket, 7002, Some("QEST-20261007-WCJQSG"), &quests)
                .await
                .is_err(),
            "a session that doesn't continue the steward takes nothing of its"
        );
        let logs = socket.with_file_name("sessions").join("--home-joel--");
        fs::create_dir_all(&logs).expect("made");
        fs::write(
            logs.join("2026-11-15T17-00-00-000Z_s-weigh.jsonl"),
            "{\"type\":\"session\",\"id\":\"s-weigh\",\"parentSession\":\"s-steward\"}\n",
        )
        .expect("written");
        stops(&store, "s-steward");
        assert_eq!(
            claims(&socket, 7003, Some("QEST-20261007-WCJQSG"), &quests).await,
            Err(
                "OSPHT4's session already heads QEST-20261007-WCJQSG by this node's record, so \
                 HARBOR can't: only that session hands it on, by letting go or by ending once a \
                 session continues its log, or the person"
                    .to_owned()
            ),
            "once the steward stops, its claim passes to the session continuing it, not to \
             whoever asks first"
        );
        assert_eq!(
            claims(&socket, 7002, Some("QEST-20261007-WCJQSG"), &quests).await,
            Ok(Response::Orchestrated),
            "one whose log continues it does, once the steward has stopped"
        );
    }

    /// Marks `session`'s presence in `store` as no longer living, as its
    /// pi stopping would.
    fn stops(store: &Memory, session: &str) {
        let presence = store
            .presences()
            .into_iter()
            .find(|presence| presence.session == session)
            .expect("its presence is here");
        store.start_here(session, (*presence.body).clone(), false);
    }

