    // A2VLJN (2026-11-21): a carry asks whether its sessions' starts are
    // taken before it tells any to end, so the ask gives the refusal a
    // start would, and starts nothing where it would be taken.
    #[tokio::test]
    async fn whether_a_start_is_taken_is_judged_as_its_start_and_starts_nothing() {
        let dir = tempfile::tempdir().expect("a temporary folder");
        let socket = dir.path().join("skiff").join("work.sock");
        let store = Memory::default();
        let (_stop, _node, _client) =
            orchestrated_in(&store, &socket, &orchestrations(), &[]).await;
        let osprey = facts::Machine {
            system: Some("macos".to_owned()),
            ..fenced("osprey", &["remote"])
        };
        store.put_machine(&osprey).expect("what it said is kept");
        declares_runs(&socket, true);
        asks_below(&socket, 7001);
        let held = Start {
            work: work(vec![Need::Machine("osprey".to_owned())]),
            folder: None,
            command: vec!["pi".to_owned()],
            may_cost: false,
            carries: false,
            once: None,
            strict: false,
        };
        let asking = || {
            Request::Takes(Taking {
                starts: vec![held.clone()],
                ordered: false,
            })
        };
        let book = socket.with_file_name("starts.jsonl");
        let kept = || fs::read_to_string(&book).map_or(0, |kept| kept.lines().count());
        let before = kept();
        let taken = ask(socket.clone(), asking()).await;
        assert_eq!(kept(), before, "the ask keeps nothing in the book");
        assert!(
            matches!(&taken, Err(why) if why.contains("starts nothing held on a Mac")),
            "an agent's is refused for the Mac it names: {taken:?}"
        );
        assert_eq!(
            taken,
            ask(socket.clone(), Request::Start(held.clone())).await,
            "as its start is"
        );
        assert!(kept() > before, "which the start keeps");
        let stop = socket.with_file_name("starts.stopped");
        fs::write(&stop, "").expect("the person's stop");
        let stopped = ask(socket.clone(), asking()).await;
        assert!(
            matches!(&stopped, Err(why) if why.starts_with("the person stopped agents")),
            "the person's stop on agents' starts is weighed first: {stopped:?}"
        );
        fs::remove_file(&stop).expect("resumed");
        asks_as_person(&socket);
        let Ok(Response::Placement(Placement::Placed { machine, .. })) =
            ask(socket.clone(), asking()).await
        else {
            panic!("the person's start is taken");
        };
        assert_eq!(machine, "osprey", "by the machine it names");
        assert_eq!(
            ask(socket, Request::Start(held)).await,
            Err("no link reaches osprey now".to_owned()),
            "which a start of it would reach for, as the ask didn't"
        );
    }

    // An orchestrator past its eight starts an hour still carries, since
    // its ordered arrivals start uncounted, and the ask weighs a carry's
    // starts together, so one past the limit is refused before any
    // session ends.
    #[tokio::test]
    async fn an_ordered_carrys_arrivals_are_weighed_uncounted_and_together() {
        let dir = tempfile::tempdir().expect("a temporary folder");
        let socket = dir.path().join("skiff").join("work.sock");
        let store = Memory::default();
        let (_stop, _node, _client) =
            orchestrated_in(&store, &socket, &orchestrations(), &[]).await;
        declares_runs(&socket, true);
        asks_below(&socket, 7001);
        let new_work = || Start {
            work: work(vec![Need::Machine("skiff".to_owned())]),
            folder: None,
            strict: false,
            command: vec!["pi".to_owned()],
            may_cost: false,
            carries: false,
            once: None,
        };
        let unstarted = Err("skiff's node starts no sessions".to_owned());
        for _ in 0..starts::CELL_AN_HOUR - 1 {
            assert_eq!(
                ask(socket.clone(), Request::Start(new_work())).await,
                unstarted
            );
        }
        let arrival = |session: &str| {
            let one = crate::carry::Done {
                session: session.to_owned(),
                started_before: None,
            };
            // From this machine, as an ordered carry's are; to it as
            // well, so placement here measures nothing of a link.
            crate::carry::arriving("QEST-20261107-HARBOR", "skiff", "skiff", &one, None)
        };
        let takes = |starts, ordered| {
            let socket = socket.clone();
            async move { ask(socket, Request::Takes(Taking { starts, ordered })).await }
        };
        let book = socket.with_file_name("starts.jsonl");
        let kept = || fs::read_to_string(&book).map_or(0, |kept| kept.lines().count());
        let before = kept();
        let one = takes(vec![arrival("s-a")], false).await;
        assert!(
            matches!(&one, Ok(Response::Placement(Placement::Placed { machine, .. })) if machine == "skiff"),
            "one more start fits the cell's eight: {one:?}"
        );
        let two = takes(vec![arrival("s-a"), arrival("s-b")], false).await;
        assert!(
            matches!(&two, Err(why) if why.contains("a cell starts at most 8 an hour")),
            "two don't, weighed together: {two:?}"
        );
        assert_eq!(kept(), before, "neither ask kept anything in the book");
        assert_eq!(
            ask(socket.clone(), Request::Start(new_work())).await,
            unstarted
        );
        let before = kept();
        let full = takes(vec![arrival("s-a")], false).await;
        assert!(
            matches!(&full, Err(why) if why.contains("a cell starts at most 8 an hour")),
            "the cell's eight leave no room: {full:?}"
        );
        let ordered = takes(vec![arrival("s-a"), arrival("s-b"), arrival("s-c")], true).await;
        assert!(
            matches!(&ordered, Ok(Response::Placement(Placement::Placed { .. }))),
            "an ordered carry's arrivals go uncounted: {ordered:?}"
        );
        let elsewhere = |session: &str| {
            let one = crate::carry::Done {
                session: session.to_owned(),
                started_before: None,
            };
            crate::carry::arriving("QEST-20261107-HARBOR", "kestrel", "skiff", &one, None)
        };
        let not_from_here = takes(vec![elsewhere("s-a")], true).await;
        assert!(
            matches!(&not_from_here, Err(why) if why.contains("a cell starts at most 8 an hour")),
            "an arrival from another machine is no carry from here: {not_from_here:?}"
        );
        let fooled = takes(vec![new_work(), new_work()], true).await;
        assert!(
            matches!(&fooled, Err(why) if why.contains("a cell starts at most 8 an hour")),
            "but ordered frees only a carry's arrival, word for word: {fooled:?}"
        );
        assert_eq!(kept(), before, "no ask keeps anything in the book");
        let many = takes(vec![arrival("s-a"); TAKES_MOST + 1], true).await;
        assert!(
            matches!(&many, Err(why) if why.contains("past the 128 an ask weighs")),
            "an ask is bounded: {many:?}"
        );
    }

    /// Tern, as `store` keeps it, saying its strict fence runs nothing.
    fn tern_runs_nothing(store: &Memory) {
        let mut tern = fenced("tern", &["remote"]);
        let declared = tern.declared.as_mut().expect("declared");
        let fences = declared.fence.as_mut().expect("a fence");
        fences
            .get_mut(&crate::declared::Kind::Strict)
            .expect("its strict fence")
            .runs
            .clear();
        store.put_machine(&tern).expect("what it said is kept");
    }

    // Here is judged by its own launcher, as a run here would be, so an
    // agent's run goes nowhere once neither here nor tern runs a command.
    #[tokio::test]
    async fn an_agents_run_goes_nowhere_here_when_here_runs_no_command() {
        let dir = tempfile::tempdir().expect("a temporary folder");
        let socket = dir.path().join("skiff").join("work.sock");
        let store = Memory::default();
        let (_stop, _node, _client) =
            orchestrated_in(&store, &socket, &orchestrations(), &[]).await;
        tern_runs_nothing(&store);
        declares_runs(&socket, false);
        asks_below(&socket, 7001);

        assert_eq!(
            run_through(socket.clone(), run_of("skiff", "true"))
                .await
                .err(),
            Some(
                "this asks as a strictly fenced agent, so it runs here only in that fence: \
                 this machine declares no way to run a command as its strictly fenced \
                 sessions run"
                    .to_owned()
            ),
            "here's launcher judges here, as a run here would be judged"
        );
        assert_eq!(
            run_through(socket.clone(), run_of("tern", "true"))
                .await
                .err(),
            Some(
                "this asks as a strictly fenced agent, so it runs only where that fence runs a \
                 command: tern declares no way to run a command as its strictly fenced \
                 sessions run that its launcher accepts, or its node is too old to say one"
                    .to_owned()
            ),
            "a run naming tern is told why not tern, never why not here"
        );
        let unnamed = Run {
            work: work(Vec::new()),
            ..run_of("skiff", "true")
        };
        assert_eq!(
            run_through(socket.clone(), unnamed).await.err(),
            Some(
                "this asks as a strictly fenced agent, so it runs here only in that fence: \
                 this machine declares no way to run a command as its strictly fenced \
                 sessions run; nor elsewhere: tern refuses: tern declares no way to run a \
                 command as its strictly fenced sessions run that its launcher accepts, or \
                 its node is too old to say one"
                    .to_owned()
            ),
            "a run naming no machine is told why not here, and why nowhere else"
        );
        let toward_tern = Work {
            prefers: vec![Need::Machine("tern".to_owned())],
            ..work(Vec::new())
        };
        let answer = placement_through(socket.clone(), Request::Place(toward_tern)).await;
        let Placement::Refused { misses } = answer else {
            panic!("no machine takes it: {answer:?}");
        };
        assert_eq!(
            misses
                .iter()
                .map(|miss| miss.machine.as_str())
                .collect::<Vec<_>>(),
            ["skiff", "tern"],
            "neither here nor tern runs it: {}",
            placement::said(&misses)
        );
        // Nor does a session an agent starts land here, as on a Mac, whose
        // node declares no launcher: it would run looser than its asker.
        let held = |needs| {
            Request::Start(Start {
                work: work(needs),
                folder: None,
                command: vec!["pi".to_owned()],
                may_cost: false,
                carries: false,
                once: None,
                strict: false,
            })
        };
        assert_eq!(
            ask(
                socket.clone(),
                held(vec![Need::Machine("skiff".to_owned())])
            )
            .await,
            Err(
                "this asks as a strictly fenced agent, so it starts only where that fence runs \
                 a command: this machine declares no way to run a command as its strictly \
                 fenced sessions run"
                    .to_owned()
            ),
            "an agent's start pinned here is refused here, saying why"
        );
        let unnamed = ask(socket, held(Vec::new())).await;
        assert!(
            unnamed.as_ref().is_err_and(|why| why.contains(
                "this machine declares no way to run a command as its strictly fenced sessions run"
            )),
            "and one naming no machine starts nowhere, saying why not here: {unnamed:?}"
        );
    }

    // Here's words run a command, but the program they name isn't there,
    // which only here's launcher sees: placement refuses here for it, and
    // what this machine says of itself names no runs, so no other machine
    // offers it the run either.
    #[tokio::test]
    async fn a_launcher_here_that_isnt_there_runs_nothing_here_and_says_none() {
        let dir = tempfile::tempdir().expect("a temporary folder");
        let socket = dir.path().join("skiff").join("work.sock");
        let store = Memory::default();
        let (_stop, _node, _client) =
            orchestrated_in(&store, &socket, &orchestrations(), &[]).await;
        asks_below(&socket, 7001);
        let says = |socket: PathBuf| async move {
            let Ok(Response::Machine(machine)) = ask(socket, Request::Machine).await else {
                panic!("the node says its machine")
            };
            machine
                .declared
                .and_then(|declared| declared.fence)
                .and_then(|mut fences| fences.remove(&crate::declared::Kind::Strict))
                .map(|doors| doors.runs)
        };
        assert_eq!(
            says(socket.clone()).await,
            Some(Vec::new()),
            "a launcher that isn't there is said as none"
        );
        let here = work(vec![Need::Machine("skiff".to_owned())]);
        let answer = placement_through(socket.clone(), Request::Place(here)).await;
        let Placement::Refused { misses } = answer else {
            panic!("here doesn't take it: {answer:?}");
        };
        let why = refused_on(&misses, "skiff", placement::RUNS_NOTHING).unwrap_or_default();
        assert!(
            why.contains("launcher /nix/store/0000-fence/bin/fence isn't there"),
            "here's launcher, not its words, refuses it: {}",
            placement::said(&misses)
        );
        declares_runs(&socket, true);
        assert!(
            says(socket)
                .await
                .is_some_and(|runs| runs.last().map(String::as_str) == Some("--")),
            "a launcher it takes is said whole"
        );
    }

    #[tokio::test]
    async fn a_fenced_agent_is_never_offered_looser_ground() {
        let dir = tempfile::tempdir().expect("a temporary folder");
        let socket = dir.path().join("skiff").join("work.sock");
        let store = Memory::default();
        let (_stop, _node, _client) =
            orchestrated_in(&store, &socket, &orchestrations(), &[]).await;
        store
            .put_machine(&fenced("tern", &["remote", "cloud"]))
            .expect("what it said is kept");
        // Here runs a command in its fence, so only tern's ground is judged.
        declares_runs(&socket, true);
        let looser = "tern refuses: tern's strictly fenced session opens builders cloud, which \
                      here's doesn't, so the session would land looser there";
        // Work that would rather go to tern, so ranking alone would send it
        // there: only its looser ground keeps it here.
        let toward_tern = Work {
            prefers: vec![Need::Machine("tern".to_owned())],
            ..work(Vec::new())
        };
        let place = |socket: PathBuf| {
            let toward_tern = toward_tern.clone();
            async move {
                let asked = tokio::task::spawn_blocking(move || {
                    Client::connect(&socket)
                        .expect("the client connects")
                        .ask(&Request::Place(toward_tern))
                        .expect("the node answers")
                });
                let answer = tokio::time::timeout(PATIENCE, asked)
                    .await
                    .expect("the node answers in time")
                    .expect("the client asks");
                let Ok(Response::Placement(placement)) = answer else {
                    panic!("a placement: {answer:?}");
                };
                placement
            }
        };
        asks_below(&socket, 7001);
        let Placement::Placed { machine, passed } = place(socket.clone()).await else {
            panic!("here takes it");
        };
        assert_eq!(
            machine, "skiff",
            "an agent is placed here, never on looser ground"
        );
        assert!(
            placement::said(&passed).contains(looser),
            "and is told why not there: {}",
            placement::said(&passed)
        );
        let unnamed = Run {
            work: work(Vec::new()),
            ..run_of("skiff", SAYS_ITS_FENCE)
        };
        assert_eq!(
            run_through(socket.clone(), unnamed)
                .await
                .expect("it runs here")
                .out,
            b"strict\n",
            "an agent's run naming no machine stays here, on its own ground, in its own \
             launcher"
        );
        asks_as_person(&socket);
        let Placement::Placed { passed, .. } = place(socket).await else {
            panic!("somewhere takes the person's");
        };
        assert!(
            !placement::said(&passed).contains("looser"),
            "the person's work isn't held to an agent's ground: {}",
            placement::said(&passed)
        );
    }

