    #[test]
    fn a_machine_booked_for_one_asker_takes_only_its_starts() {
        let asker = |told: &str| Admits::Asker(told.to_owned());
        assert!(
            !asker(made::PERSON).takes(Some("P9R1KI")),
            "the person's starts never go where an agent's make booked, since that agent \
             wrote its worker home"
        );
        assert!(
            asker(made::PERSON).takes(Some(made::PERSON)),
            "they go where the person's make booked"
        );
        assert!(
            asker("P9R1KI").takes(Some("P9R1KI")),
            "its own asker's starts go there"
        );
        assert!(
            !asker("QK4T7Z").takes(Some("P9R1KI")),
            "another agent's starts go elsewhere"
        );
        assert!(
            !asker(made::UNKNOWN).takes(Some(made::UNKNOWN)),
            "a start from no one known takes no booked machine"
        );
        assert!(
            asker(made::PERSON).takes(None) && !asker("P9R1KI").takes(None),
            "a machine whose make told no asker takes only the person's starts"
        );
        assert!(
            Admits::All.takes(Some("P9R1KI")),
            "a pinned start goes there"
        );
    }

    #[tokio::test]
    async fn another_agents_start_is_never_placed_on_a_machine_made_for_one_asker() {
        let (to_dial, _) = mpsc::unbounded_channel();
        let membership = Realm {
            name: "work".to_owned(),
            machine: "skiff".to_owned(),
        };
        let (shared, _) = Shared::of(
            Memory::default(),
            (membership.hello(), "/nowhere/node".into()),
            bare("/nowhere/steer".into(), None),
            to_dial,
        );
        shared
            .store
            .put_machine(&placement::tests::machine(
                "osprey",
                "linux",
                32,
                &["basin"],
            ))
            .expect("the made machine is kept");
        let mut made = made_by("/usr/bin/lend", "osprey", jiff::Timestamp::now());
        made.asker = Some("P9R1KI".to_owned());
        shared.book_for(&made);
        let basin = work(vec![Need::Reach("basin".to_owned())]);
        let placed = |told: &str| match shared.place(
            &basin,
            Counts::Always,
            None,
            Screen::Ground,
            &Admits::Asker(told.to_owned()),
        ) {
            Placement::Placed { machine, .. } => Some(machine),
            _ => None,
        };
        assert_eq!(
            placed("QK4T7Z"),
            None,
            "another agent's start isn't placed there"
        );
        assert_eq!(
            placed("P9R1KI").as_deref(),
            Some("osprey"),
            "its asker's start is"
        );
        assert_eq!(
            placed(made::PERSON),
            None,
            "but not the person's, which would read the worker home the agent wrote"
        );
        made.asker = None;
        shared.book_for(&made);
        assert_eq!(
            (placed("P9R1KI"), placed(made::PERSON).as_deref()),
            (None, Some("osprey")),
            "a machine whose make told no asker takes only the person's starts"
        );
        assert!(
            !shared.admitted_on("osprey", &Admits::Asker("P9R1KI".to_owned()))
                && shared.admitted_on("tern", &Admits::Asker("P9R1KI".to_owned())),
            "a carry is refused a booked machine and let onto one not booked"
        );
        let mut here = made_by("/usr/bin/lend", "skiff", jiff::Timestamp::now());
        here.asker = Some("QK4T7Z".to_owned());
        shared.book_for(&here);
        let anywhere = work(Vec::new());
        assert_eq!(
            match shared.place(
                &anywhere,
                Counts::Always,
                None,
                Screen::Ground,
                &Admits::Asker("P9R1KI".to_owned()),
            ) {
                Placement::Placed { machine, .. } => Some(machine),
                _ => None,
            }
            .as_deref(),
            Some("skiff"),
            "this machine takes every asker's starts, whatever names it"
        );
        assert_ne!(
            shared.admits().await,
            Admits::All,
            "once a machine is booked, a start is held to who asks"
        );
    }

    #[test]
    fn a_start_within_the_strict_launcher_needs_a_folder_away_from_home() {
        use crate::declared::Kind;
        use start::Needs;
        let pi = vec!["pi".to_owned()];
        let sh = vec!["sh".to_owned()];
        assert_eq!(
            needs_its_folder(false, true, Some(Kind::Strict), (&pi, "pi")),
            Needs::AwayFromHome,
            "where the node fences, a strict start runs in its launcher, which won't write home"
        );
        assert_eq!(
            needs_its_folder(true, false, Some(Kind::Strict), (&sh, "pi")),
            Needs::AwayFromHome,
            "so does any command but pi's own, wherever it runs, strict or not"
        );
        assert_eq!(
            needs_its_folder(false, false, Some(Kind::Strict), (&pi, "pi")),
            Needs::Nothing,
            "pi fencing itself begins at home, as before"
        );
        assert_eq!(
            needs_its_folder(false, true, Some(Kind::Fence), (&pi, "pi")),
            Needs::Nothing,
            "as does one in the ordinary fence"
        );
        assert_eq!(
            needs_its_folder(true, false, None, (&pi, "pi")),
            Needs::ItsFolder,
            "and a strict start always needs the folder it names"
        );
    }

    #[test]
    fn a_held_start_goes_through_its_fence_only_where_the_node_fences_it() {
        use crate::declared::Kind;
        let launch = |kind: Kind| Ok(vec!["fence".to_owned(), format!("{kind}"), "--".to_owned()]);
        let launched = |kind: Kind| launch(kind).expect("a launcher");
        let words = |said: &[&str]| said.iter().map(|&word| word.to_owned()).collect::<Vec<_>>();
        let pi = words(&["pi", "--session", "s-harbour"]);
        let pi_held = (pi.as_slice(), "pi");
        assert_eq!(
            held_within(true, Some(Kind::Strict), pi_held, launch),
            Ok(launched(Kind::Strict)),
            "on a Mac, within the launcher of the fence it was placed in"
        );
        assert_eq!(
            held_within(false, Some(Kind::Strict), pi_held, launch),
            Ok(words(&["/usr/bin/env", "PI_SANDBOX=strict"])),
            "elsewhere, pi fences itself, told which fence"
        );
        assert_eq!(
            held_within(false, Some(Kind::Fence), pi_held, launch),
            Ok(words(&[
                "/usr/bin/env",
                "PI_SANDBOX=fence",
                "PI_FENCE_DECLARED=1"
            ])),
            "and the fence, marked declared so pi doesn't lift it"
        );
        let harnessed = words(&[
            "env",
            "PI_SANDBOX=strict",
            "QUEST_WORKFLOW_AUTOLOAD_ID=QEST-20261107-HARBOR",
            "pi-claude",
            "-c",
        ]);
        assert_eq!(
            held_within(false, Some(Kind::Strict), (&harnessed, "pi-claude"), launch),
            Ok(words(&["/usr/bin/env", "PI_SANDBOX=strict"])),
            "as is the realm's agent program, after what a harness sets"
        );
        for unfenced in [None, Some(Kind::None)] {
            for fences in [true, false] {
                assert_eq!(
                    held_within(fences, unfenced, (&words(&["sh"]), "pi"), launch),
                    Ok(Vec::new()),
                    "the person's, or one unfenced, as asked"
                );
            }
        }
        assert_eq!(
            held_within(true, Some(Kind::Fence), pi_held, |_| Err(
                "refused".to_owned()
            )),
            Err("refused".to_owned()),
            "a launcher refused starts nothing, rather than outside its fence"
        );
        assert_eq!(
            starts_in(Some(Kind::Fence), Screen::Run),
            None,
            "an agent shown unfenced starts unfenced, as a Mac took it before"
        );
        assert_eq!(
            starts_in(Some(Kind::Strict), Screen::Held),
            Some(Kind::Strict),
            "any other in the fence it was placed in"
        );
    }

    #[test]
    fn pi_fences_itself_only_named_bare_or_as_a_carried_arrival() {
        use crate::declared::Kind;
        let launch = |kind: Kind| Ok(vec!["fence".to_owned(), format!("{kind}"), "--".to_owned()]);
        let launched = |kind: Kind| launch(kind).expect("a launcher");
        let words = |said: &[&str]| said.iter().map(|&word| word.to_owned()).collect::<Vec<_>>();
        let arrival = crate::carry::arriving(
            "QEST-20261107-HARBOR",
            "skiff",
            "tern",
            &crate::carry::Done {
                session: "s-harbour".to_owned(),
                started_before: None,
            },
            None,
        )
        .command;
        assert_eq!(
            held_within(false, Some(Kind::Strict), (&arrival, "pi"), launch),
            Ok(words(&["/usr/bin/env", "PI_SANDBOX=strict"])),
            "as is a carried session's arrival, word for word"
        );
        let mut tampered = arrival.clone();
        tampered[2].push_str("; sh");
        let others = [
            words(&["bash", "-c", "pi"]),
            words(&["sh"]),
            words(&["./pi"]),
            words(&["/tmp/pi"]),
            words(&["env", "PI_SANDBOX=off", "pi"]),
            words(&["env", "PI_SANDBOX=fence", "pi"]),
            words(&["env", "NODE_OPTIONS=--require=x", "pi"]),
            words(&["env", "LD_PRELOAD=x.so", "pi"]),
            words(&["env", "-u", "PI_SANDBOX", "pi"]),
            words(&["env", "PI_SPAWNER=$(sh)", "pi"]),
            words(&["env"]),
            Vec::new(),
            tampered,
        ];
        for other in &others {
            assert_eq!(
                held_within(false, Some(Kind::Strict), (other, "pi"), launch),
                Ok(launched(Kind::Strict)),
                "anything else an agent in a fence holds runs within its launcher: {other:?}"
            );
        }
        assert_eq!(
            held_within(false, Some(Kind::Fence), (&others[0], "pi"), |_| {
                Err("refused".to_owned())
            }),
            Err("refused".to_owned()),
            "and where its launcher is refused, starts nothing"
        );
    }

    #[test]
    fn pi_fences_itself_only_with_arguments_that_resume_it_or_prompt_it() {
        use crate::declared::Kind;
        let launch = |kind: Kind| Ok(vec!["fence".to_owned(), format!("{kind}"), "--".to_owned()]);
        let words = |said: &[&str]| said.iter().map(|&word| word.to_owned()).collect::<Vec<_>>();
        let itself = words(&["/usr/bin/env", "PI_SANDBOX=strict"]);
        let spawned = |script: &str| {
            words(&[
                "env",
                "QUEST_WORKFLOW_AUTOLOAD_ID=QEST-20261107-HARBOR",
                "QUEST_WORKFLOW_FIRST_WORDS=w-harbour",
                "QUEST_WORKFLOW_FIRST_TEXT=mend the harbour; then $(sh) -e x",
                "PI_SANDBOX=strict",
                "sh",
                "-c",
                script,
            ])
        };
        for fencing in [
            spawned("pi"),
            spawned("pi-claude"),
            spawned("pi --session s-harbour"),
            spawned("pi-claude --session 01a1fa83-84a3"),
            words(&["pi", "-c"]),
            words(&["pi", "--continue", "mend the harbour"]),
            words(&[
                "env",
                "PI_SANDBOX=strict",
                "pi",
                "--session",
                "s-1",
                "go on",
            ]),
        ] {
            assert_eq!(
                held_within(false, Some(Kind::Strict), (&fencing, "pi-claude"), launch),
                Ok(itself.clone()),
                "a harness's held spawn, or pi resumed or prompted, fences itself: {fencing:?}"
            );
        }
        for other in [
            words(&["pi", "-e", "x.ts"]),
            words(&["pi", "--extension", "x.ts"]),
            words(&["pi", "-a"]),
            words(&["pi", "--approve"]),
            words(&["pi", "--model", "m"]),
            words(&["pi", "@.ssh/id_ed25519"]),
            words(&["pi", "a prompt", "-e"]),
            words(&["pi", "--session"]),
            words(&["pi", "--session", "$(sh)"]),
            spawned("pi; sh"),
            spawned("pi --session s-1 -e x.ts"),
            spawned("pi  -c"),
            spawned("/tmp/pi"),
            spawned("pi mend"),
            [spawned("pi"), words(&["extra"])].concat(),
        ] {
            assert_eq!(
                held_within(false, Some(Kind::Strict), (&other, "pi-claude"), launch),
                Ok(words(&["fence", "strictly fenced", "--"])),
                "pi loading code, loosened, or run by a script of more, goes through its launcher: \
                 {other:?}"
            );
        }
    }

    #[test]
    fn pi_fences_itself_only_in_the_environment_and_script_a_harness_gives_it() {
        use crate::declared::Kind;
        let launch = |kind: Kind| Ok(vec!["fence".to_owned(), format!("{kind}"), "--".to_owned()]);
        let words = |said: &[&str]| said.iter().map(|&word| word.to_owned()).collect::<Vec<_>>();
        let spawned = |set: &[&str], script: &str| {
            [words(&["env"]), words(set), words(&["sh", "-c", script])].concat()
        };
        let fences = |command: &[String]| {
            held_within(false, Some(Kind::Strict), (command, "pi-claude"), launch)
                == Ok(words(&["/usr/bin/env", "PI_SANDBOX=strict"]))
        };
        let quest = "QUEST_WORKFLOW_AUTOLOAD_ID=QEST-20261107-HARBOR";
        for set in [
            vec![quest],
            vec![
                quest,
                "QUEST_WORKFLOW_FIRST_WORDS=w-harbour",
                "PI_SANDBOX=strict",
            ],
            vec![
                "QUEST_WORKFLOW_FIRST_TEXT=mend the harbour",
                "PI_SANDBOX=strict",
            ],
        ] {
            assert!(fences(&spawned(&set, "pi")), "what a harness sets: {set:?}");
        }
        for other in [
            "PI_SANDBOX=fence",
            "PI_SANDBOX=off",
            "PI_SANDBOX=",
            "PI_FENCE_DECLARED=1",
            "PI_FENCE_STAGE=lifted",
            "PI_SPAWNER=off",
            "PI_CODING_AGENT_DIR=x",
            "PATH=/tmp",
            "LD_LIBRARY_PATH=/tmp",
            "BASH_ENV=x",
            "ENV=x",
            "NODE_OPTIONS=--require=x",
            "QUEST_WORKFLOW_AUTOLOAD_ID=$(sh)",
            "QUEST_WORKFLOW_FIRST_WORDS=a word",
            "QUEST_WORKFLOW_FIRST_TEXT=!sh",
            "QUEST_WORKFLOW_FIRST_TEXT=/login",
            "QUEST_WORKFLOW_FIRST_TEXT=",
        ] {
            assert!(
                !fences(&spawned(&[quest, other], "pi")),
                "any other name, or a value past what it holds, goes through the launcher: {other}"
            );
        }
        for command in [words(&["pi", "!sh"]), words(&["pi", "/login"])] {
            assert!(
                !fences(&command),
                "nor is a command its prompt: {command:?}"
            );
        }
        for script in [
            "pi-claude -c",
            "pi --continue",
            "pi --session",
            "pi --session s-1 go",
            "pi --session 's-1'",
            "pi --session $ID",
            "'pi'",
            "$PI",
            "pi\n",
            " pi",
            "pi-claude\tpi",
        ] {
            assert!(
                !fences(&spawned(&[quest], script)),
                "a script past the program, resumed by a plain id, goes through it: {script:?}"
            );
        }
    }

    #[test]
    fn a_held_spawns_first_text_is_never_read_by_a_shell() {
        // The start as the node runs it, through the script its login
        // shell is given, but in `sh` alone, without a profile.
        let through = start::login_shell("harbour", None);
        let lic = through
            .iter()
            .position(|word| word == "-lic")
            .expect("a login shell");
        let through = [
            vec!["sh".to_owned(), "-c".to_owned()],
            through[lic + 1..].to_vec(),
        ]
        .concat();
        let starts = |text: &str, script: &str| {
            let folder = tempfile::tempdir().expect("a temporary folder");
            let command: Vec<String> = ["env", &format!("{FIRST_TEXT}{text}"), "sh", "-c", script]
                .iter()
                .map(|&word| word.to_owned())
                .collect();
            let fences = fences_itself(&command, "true");
            let ran = std::process::Command::new(&through[0])
                .args(&through[1..])
                .args(&command)
                .current_dir(folder.path())
                .status()
                .expect("a shell");
            assert!(ran.success(), "it runs: {text:?}");
            (fences, folder.path().join("x").exists())
        };
        for text in [
            "$(touch x)",
            "`touch x`",
            "mend\ntouch x",
            "; touch x",
            "\"; touch x; \"",
            "$(touch x) `touch x` ; touch x",
        ] {
            assert_eq!(
                starts(text, "true"),
                (true, false),
                "its first text is one word, never read by a shell: {text:?}"
            );
        }
        assert_eq!(
            starts("touch x", "eval \"$QUEST_WORKFLOW_FIRST_TEXT\""),
            (false, true),
            "where a script would read it, the file appears, and it isn't pi fencing itself"
        );
    }

    #[test]
    fn a_carry_from_here_brings_its_session_back_declaring_the_fence_it_ran_in() {
        use crate::declared::Kind;
        let one = crate::carry::Done {
            session: "s-harbour".to_owned(),
            started_before: None,
        };
        let arriving =
            crate::carry::arriving("QEST-20261107-HARBOR", "skiff", "tern", &one, None).command;
        let strict = |session: &str| {
            assert_eq!(
                session, "s-harbour",
                "the session carried is the one weighed"
            );
            Kind::Strict
        };
        assert_eq!(
            declaring_carried(&arriving, "skiff", None, strict),
            Some(DeclaredFence {
                kind: FenceKind::Strict,
                from: FenceFrom::Default,
            }),
            "a strict session carried by an asker in the agent fence arrives strict"
        );
        assert_eq!(
            declaring_carried(&arriving, "skiff", None, |_| Kind::None),
            None,
            "an unfenced one arrives as asked"
        );
        assert_eq!(
            declaring_carried(&arriving, "kestrel", None, strict),
            None,
            "one carried from another machine is that machine's to weigh"
        );
        assert_eq!(
            declaring_carried(&["pi".to_owned()], "skiff", None, strict),
            None,
            "any other start declares as it was asked"
        );
    }

    // A carried session has ended by the time its arrival is asked for,
    // so what it ran in is read from the carry kept for it.
    #[tokio::test]
    async fn an_arrival_declares_the_fence_its_carry_was_judged_by() {
        let dir = tempfile::tempdir().expect("a temporary folder");
        let carries = dir.path().join("carries.jsonl");
        let (to_dial, _) = mpsc::unbounded_channel();
        let membership = Realm {
            name: "work".to_owned(),
            machine: "skiff".to_owned(),
        };
        let (shared, _) = Shared::of(
            Memory::default(),
            (membership.hello(), "/nowhere/node".into()),
            Given {
                carries: carries.clone(),
                ..bare("/nowhere/steer".into(), None)
            },
            to_dial,
        );
        let arriving = |session: &str| {
            let one = crate::carry::Done {
                session: session.to_owned(),
                started_before: None,
            };
            crate::carry::arriving("QEST-20261107-HARBOR", "skiff", "tern", &one, None)
        };
        let declared = |kind| {
            Some(DeclaredFence {
                kind,
                from: FenceFrom::Default,
            })
        };
        let kept = |session: &str, fence: &str| {
            ordered::keep(
                &carries,
                &serde_json::json!({
                    "at": jiff::Timestamp::now().to_string(),
                    "session": session,
                    "from": "skiff",
                    "to": "tern",
                    "fence": fence,
                }),
            )
            .expect("the carry is kept");
        };
        kept("s-harbour", "fence");
        kept("s-quay", "strict");
        assert_eq!(
            shared
                .brought_back_declaring(arriving("s-harbour"))
                .work
                .fence,
            declared(FenceKind::Fence),
            "in the fence its carry was judged in"
        );
        assert_eq!(
            shared.brought_back_declaring(arriving("s-quay")).work.fence,
            declared(FenceKind::Strict),
            "a strict one arrives strict, though its carrier runs looser"
        );
        assert_eq!(
            shared
                .brought_back_declaring(arriving("s-wharf"))
                .work
                .fence,
            declared(FenceKind::Strict),
            "one gone with no carry kept arrives strict, never unfenced"
        );
    }

    #[test]
    fn a_bare_resume_declares_at_least_the_fence_its_session_ran_in() {
        use crate::declared::Kind;
        let words = |all: &[&str]| all.iter().map(|one| (*one).to_owned()).collect::<Vec<_>>();
        let resume = |session: &str| words(&["pi", "--session", session]);
        let fenced = |session: &str| {
            assert_eq!(
                session, "s-harbour",
                "the session resumed is the one weighed"
            );
            Kind::Fence
        };
        let declared = |kind| {
            Some(DeclaredFence {
                kind,
                from: FenceFrom::Default,
            })
        };
        assert_eq!(
            declaring_resumed(&resume("s-harbour"), None, fenced),
            declared(FenceKind::Fence),
            "a resume asked with no fence takes the one its session ran in"
        );
        assert_eq!(
            declaring_resumed(&resume("s-harbour"), declared(FenceKind::Strict), fenced),
            declared(FenceKind::Strict),
            "one asked stricter stays so"
        );
        assert_eq!(
            declaring_resumed(&resume("s-harbour"), None, |_| Kind::None),
            None,
            "one never seen fenced declares as it was asked"
        );
        assert_eq!(
            declaring_resumed(
                &words(&["pi", "--session", "s-harbour", "-p", "hi"]),
                None,
                fenced
            ),
            None,
            "a start that does more than resume isn't one"
        );
    }

    // 315D0071, Tue 24 Nov: after a Mac boots, its sessions come back as
    // launchd's starts, which declare no fence, so the node raises each
    // to what that session was seen in before.
