    /// The README of quest `id` of `realm`, making `claims` for its
    /// active `sessions`.
    fn claiming(id: &str, realm: &str, claims: &[&str], sessions: &[&str]) -> String {
        // A claim says its kind, `github-pr:` or `calendar-event:`,
        // before what it claims, or is a change's, `owner/name#N`; so no
        // claim's kind is guessed from how it's spelled.
        fn kind(claim: &str) -> (&'static str, &str) {
            if let Some(spelled) = claim.strip_prefix("github-pr:") {
                ("github-pr", spelled)
            } else if let Some(spelled) = claim.strip_prefix("calendar-event:") {
                ("calendar-event", spelled)
            } else {
                assert!(claim.contains('#'), "{claim} says no kind");
                ("github-pr", claim)
            }
        }
        let aliases: String = claims
            .iter()
            .map(|claim| {
                let (kind, value) = kind(claim);
                format!("  - type: {kind}\n    value: {value}\n")
            })
            .collect::<Vec<_>>()
            .concat();
        let listed: String = sessions
            .iter()
            .map(|session| format!("  - id: {session}\n    status: active\n"))
            .collect::<Vec<_>>()
            .concat();
        format!(
            "---\nid: {id}\nkind: quest\nstatus: active\nrealm: {realm}\naliases:\n{aliases}\
             sessions:\n{listed}---\n# A Quest\n"
        )
    }

    /// A session `id` at `address` on `machine`, standing as `state`, on
    /// `quest`.
    fn on_quest(id: &str, address: &str, machine: &str, state: &str, quest: &str) -> Session {
        serde_json::from_value(json!({
            "id": id,
            "address": address,
            "machine": machine,
            "groups": [],
            "state": state,
            "at": "2026-11-18T08:00:00Z",
            "quest": quest,
        }))
        .expect("a session")
    }

    // 8855BD77's council (23 November): a quest a session only says it
    // runs could carry another quest's trees with it.
    #[test]
    fn a_session_carrying_itself_takes_its_quests_trees_only_where_recorded_in_it() {
        let quest = "QEST-20261115-HARBOR";
        let alone = [on_quest("s-harbour", "HARBOR", "skiff", "idle", quest)];
        let asking = (quest, "s-harbour", "skiff");
        assert!(
            carries_whole(true, asking, &alone),
            "recorded in it, and alone in it here, it takes the quest's trees"
        );
        assert!(
            !carries_whole(false, asking, &alone),
            "only saying it runs it, it takes its own trees alone"
        );
        let beside = [
            alone[0].clone(),
            on_quest("s-ferry", "FERRY1", "skiff", "idle", quest),
        ];
        assert!(
            !carries_whole(true, asking, &beside),
            "and never while another of the quest stands here"
        );
    }

